// SPDX-License-Identifier: MIT. Fixed Microsoft WMI provider in an isolated process.
// Never call this implementation from the GUI process. The supervisor supplies
// a 10s process deadline; WMI timeout properties alone cannot prove cancellation.
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Globalization;
using System.Linq;
using System.Management;
using System.Text;
using System.Web.Script.Serialization;
using RogControl;

internal sealed class WindowsBrightnessWmi : IWindowsBrightnessNative {
 const string Scope=@"\\.\root\WMI";
 const string MonitorQuery="SELECT Active, InstanceName, CurrentBrightness, Level, Levels FROM WmiMonitorBrightness";
 const string MethodQuery="SELECT Active, InstanceName FROM WmiMonitorBrightnessMethods";
 const string FriendlyQuery="SELECT Active, InstanceName, UserFriendlyName, UserFriendlyNameLength FROM WmiMonitorID";
 static ManagementObjectSearcher Search(string query){return new ManagementObjectSearcher(new ManagementScope(Scope),new ObjectQuery(query),new EnumerationOptions{ReturnImmediately=true,Rewindable=false,Timeout=TimeSpan.FromSeconds(3)});}
 static bool? Flag(ManagementBaseObject value,string property){var raw=value[property];return raw is bool?(bool?)raw:null;}
 static string Instance(ManagementBaseObject value){return value["InstanceName"] as string;}
 static string Friendly(ManagementBaseObject value){object raw=value["UserFriendlyNameLength"];var chars=value["UserFriendlyName"] as ushort[];if(!(raw is ushort)||chars==null||(ushort)raw<1||(ushort)raw>64||chars.Length<(ushort)raw||chars.Length>128)return null;string name=new string(chars.Take((ushort)raw).Select(c=>(char)c).ToArray()).TrimEnd('\0').Trim();return name.Length==0||name.Any(c=>Char.IsControl(c)||Char.IsSurrogate(c)||Char.GetUnicodeCategory(c)==UnicodeCategory.Format)?null:name;}
 Dictionary<string,string> Names(){try{var rows=new List<KeyValuePair<string,string>>();using(var search=Search(FriendlyQuery))using(var values=search.Get())foreach(ManagementObject value in values){using(value){if(rows.Count>=WindowsBrightnessRules.MaximumMonitors)throw new InvalidOperationException();string id=Instance(value),name=Friendly(value);if(Flag(value,"Active")==true&&id!=null&&name!=null)rows.Add(new KeyValuePair<string,string>(id,name));}}return rows.GroupBy(p=>p.Key,StringComparer.Ordinal).Where(g=>g.Count()==1).ToDictionary(g=>g.Key,g=>g.First().Value,StringComparer.Ordinal);}catch(Exception){return new Dictionary<string,string>(StringComparer.Ordinal);}}
 public BrightnessRawMonitor[] ReadMonitors(){var result=new List<BrightnessRawMonitor>();var names=Names();using(var search=Search(MonitorQuery))using(var values=search.Get())foreach(ManagementObject value in values){using(value){if(result.Count>=WindowsBrightnessRules.MaximumMonitors)throw new WindowsBrightnessProtocolError("INVALID_PROVIDER_DATA");object current=value["CurrentBrightness"],count=value["Levels"];var levels=value["Level"] as byte[];string id=Instance(value),name;result.Add(new BrightnessRawMonitor{InstanceName=id,FriendlyName=id!=null&&names.TryGetValue(id,out name)?name:null,Active=Flag(value,"Active"),Current=current is byte?(int?)(byte)current:null,LevelCount=count is uint&&(uint)count<=101?(int?)(uint)count:null,Levels=levels==null?null:levels.Select(v=>(int)v).ToArray()});}}return result.ToArray();}
 public BrightnessRawMethod[] ReadMethods(){var result=new List<BrightnessRawMethod>();using(var search=Search(MethodQuery))using(var values=search.Get())foreach(ManagementObject value in values){using(value){if(result.Count>=WindowsBrightnessRules.MaximumMonitors)throw new WindowsBrightnessProtocolError("INVALID_PROVIDER_DATA");result.Add(new BrightnessRawMethod{InstanceName=Instance(value),Active=Flag(value,"Active")});}}return result.ToArray();}
 public uint SetBrightness(string exactInstanceName,int brightness){if(String.IsNullOrEmpty(exactInstanceName)||brightness<0||brightness>100)throw new WindowsBrightnessProtocolError("INVALID_REQUEST");ManagementObject selected=null;int rows=0,matches=0;try{using(var search=Search(MethodQuery))using(var values=search.Get())foreach(ManagementObject value in values){if(++rows>WindowsBrightnessRules.MaximumMonitors){value.Dispose();throw new WindowsBrightnessProtocolError("INVALID_PROVIDER_DATA");}if(Instance(value)==exactInstanceName){matches++;if(Flag(value,"Active")==true&&selected==null)selected=value;else value.Dispose();}else value.Dispose();}if(matches!=1||selected==null)throw new WindowsBrightnessProtocolError("CURRENT_CHANGED");using(var input=selected.GetMethodParameters("WmiSetBrightness")){input["Timeout"]=(uint)0;input["Brightness"]=(byte)brightness;using(var output=selected.InvokeMethod("WmiSetBrightness",input,new InvokeMethodOptions{Timeout=TimeSpan.FromSeconds(5)})){object code=output==null?null:output["ReturnValue"];if(!(code is uint))throw new WindowsBrightnessProtocolError("INVALID_METHOD_RESULT");return (uint)code;}}}finally{if(selected!=null)selected.Dispose();}}
}
internal static class WindowsBrightnessWorkerProgram {
 static int Main(string[] args){if(args.Length!=0)return 2;Console.OutputEncoding=new UTF8Encoding(false);var json=new JavaScriptSerializer{MaxJsonLength=32768,RecursionLimit=12};var clock=Stopwatch.StartNew();var service=new WindowsBrightnessService(new WindowsBrightnessWmi(),()=>clock.ElapsedMilliseconds,()=>DateTime.UtcNow);string line;while((line=OpenAc.WorkerTextProtocol.ReadLine())!=null){object id=null;Dictionary<string,object> reply;try{if(line.Length>32768)throw new WindowsBrightnessProtocolError("INVALID_REQUEST");var request=json.Deserialize<Dictionary<string,object>>(line);if(request!=null)request.TryGetValue("id",out id);var data=service.Handle(request);reply=WindowsBrightnessService.Object("id",id,"ok",true,"data",data);}catch(Exception error){var failure=error as WindowsBrightnessProtocolError;string code=failure!=null?failure.Code:error is UnauthorizedAccessException?"ACCESS_DENIED":error is ManagementException?"WMI_PROVIDER_FAILED":error is ArgumentException?"INVALID_REQUEST":"QUERY_FAILED";reply=WindowsBrightnessService.Object("id",id,"ok",false,"error",WindowsBrightnessService.Object("code",code));}Console.WriteLine(json.Serialize(reply));Console.Out.Flush();}return 0;}
}
